mapper.select:
/* isry.csemd.mngrpage.aplcnttrprmng.mapper.AplcntTrprMngMapper.selectAplyList - Lee SangHoon [신청 대상자 목록 조회] */ T.* FROM (SELECT NVL(T.TRPR_INFO_NO,'-') AS TRPR_INFO_NO -- 대상자정보번호 ,T.APLY_RCPT_SN AS APLY_RCPT_SN -- 신청접수일련번호
,T.FRST_REG_DT AS FRST_REG_DT -- 최초등록일시(등록일자) ,NVL(TO_CHAR(T02.TPRI_APLY_YMD), '-') AS TPRI_APLY_YMD -- 1차신청일자/신청일자 ,NVL(TO_CHAR(T02.SCD_APLY_YMD,'YYYY-MM-DD'), '-') AS SCD_APLY_YMD -- 2차신청일자 ,NVL(DEC_B64(T1.PRTCR_NM_ENCPT), '-') AS PRTCR_NM -- 보호자명암호화 ,NVL(DEC_B64(T1.TRPR_NM_ENCPT),'-') AS TRPR_NM -- 대상자명암호화 ,NVL(T1.TRPR_BRTH_YMD,'-') AS TRPR_BRTH_YMD -- 대상자출생일자 ,TRUNC(MONTHS_BETWEEN(SYSDATE,T1.TRPR_BRTH_YMD)/12,0) AS AGEA -- 만 나이 ,NVL((SELECT CMMNS_CD_VALUE_NM FROM SAC100 /* 공통코드 값 */ WHERE CMMNS_CD_ID = 'SXDC_SE_CD' AND CMMNS_CD_VALUE = T1.SXDC_SE_CD ),'-') AS SXDC -- 성별 ,NVL((SELECT CMMNS_CD_VALUE_NM FROM SAC100 /* 공통코드 값 */ WHERE CMMNS_CD_ID = 'ACBG_SE_CD' AND CMMNS_CD_VALUE = T3.ACBG_SE_CD ),'-') AS SCHL -- 교급 ,NVL((SELECT CMMNS_CD_VALUE_NM FROM SAC100 /* 공통코드 값 */ WHERE CMMNS_CD_ID = 'GRADE_SE_CD' AND CMMNS_CD_VALUE = T3.GRADE_SE_CD ), '-') AS GRADE -- 학년 ,NVL(DEC_B64(T.PIC_NM_ENCPT),'-') AS PIC_NM -- 담당자명암호화 ,NVL(T.RQST_INST_NM,'-') AS RQST_INST_NM -- 의뢰기관명 ,NVL(T4.SRVC_EXCN_BIZ_NM,'-') AS SRVC_EXCN_BIZ_NM -- 서비스실행사업명(과정명) ,NVL((SELECT CMMNS_CD_VALUE_NM FROM SAC100 /* 공통코드 값 */ WHERE CMMNS_CD_ID = 'APLY_RCPT_SRNG_SE_CD' AND CMMNS_CD_VALUE = SUBSTR(T.APLY_RCPT_SRNG_PRGRS_STTS_SE_CD,0,2) ),'-') AS APLY_RCPT_SRNG -- 신청접수심사(진행단계) ,NVL((SELECT CMMNS_CD_VALUE_NM FROM SAC100 /* 공통코드 값 */ WHERE CMMNS_CD_ID = 'APLY_RCPT_SRNG_PRGRS_STTS_SE_CD' AND CMMNS_CD_VALUE = T.APLY_RCPT_SRNG_PRGRS_STTS_SE_CD ),'-') AS APLY_RCPT_SRNG_PRGRS_STTS -- 신청접수심사진행상태(상태) ,NVL((SELECT CMMNS_CD_VALUE_NM FROM SAC100 /* 공통코드 값 */ WHERE CMMNS_CD_ID = 'APLY_RCPT_SRNG_PRGRS_STTS_SE_CD' AND CMMNS_CD_VALUE = T02.APLY_STTS_SE_CD ),'-') AS APLY_STTS -- 신청상태 ,NVL((SELECT CMMNS_CD_VALUE_NM FROM SAC100 /* 공통코드 값 */ WHERE CMMNS_CD_ID = 'APLY_RCPT_SRNG_PRGRS_STTS_SE_CD' AND CMMNS_CD_VALUE = T02.APLY_RVW_SE_CD ),'-') AS APLY_RVW -- 신청검토 ,NVL((SELECT CMMNS_CD_VALUE_NM FROM SAC100 /* 공통코드 값 */ WHERE CMMNS_CD_ID = 'APLY_RCPT_SRNG_PRGRS_STTS_SE_CD' AND CMMNS_CD_VALUE = T02.STG2_APLY_STTS_SE_CD ),'-') AS STG2_APLY_STTS -- 2단계 신청 ,NVL(TO_CHAR(T01.INTERN_SCORE),'-') AS INTERN_SCORE -- 내재화 점수 ,NVL(TO_CHAR(T01.EXTERN_SCORE),'-') AS EXTERN_SCORE -- 외현화 점수 ,NVL(TO_CHAR(T01.SINCERITY_EVL),'-') AS SINCERITY_EVL -- 정성평가 점수 ,NVL(TO_CHAR(T01.INTERN_SCORE*0.47 + T01.EXTERN_SCORE*0.23 + T01.SINCERITY_EVL*0.30),'-') AS PAPERS_TOTAL_SCORE -- 서류총점 ,NVL(TO_CHAR(RANK() OVER (PARTITION BY T.SRVC_EXCN_BIZ_NO ORDER BY NVL(T01.INTERN_SCORE*0.47 + T01.EXTERN_SCORE*0.23 + T01.SINCERITY_EVL*0.30,0) DESC )),'-') AS PAPERS_SRNG_RANK -- 서류심사순위 ,NVL((SELECT CMMNS_CD_VALUE_NM FROM SAC100 /* 공통코드 값 */ WHERE CMMNS_CD_ID = 'APLY_RCPT_SRNG_PRGRS_STTS_SE_CD' AND CMMNS_CD_VALUE = T02.PAPERS_RESULT_SE_CD ),'-') AS RCPT_STTS -- 접수 ,T.INTRVW_YMD AS INTRVW_YMD -- 면접일자 ,T.INTRVW_HR AS INTRVW_HR -- 면접시간 ,NVL((SELECT CMMNS_CD_VALUE_NM FROM SAC100 /* 공통코드 값 */ WHERE CMMNS_CD_ID = 'INTRVW_PTCPTN_MTHD_SE_CD' AND CMMNS_CD_VALUE = T.INTRVW_PTCPTN_MTHD_SE_CD ),'-') AS INTRVW_PTCPTN_MTHD -- 면접참여방법 ,NVL((SELECT CMMNS_CD_VALUE_NM FROM SAC100 /* 공통코드 값 */ WHERE CMMNS_CD_ID = 'INTRVW_PTCPTN_SE_CD' AND CMMNS_CD_VALUE = T.INTRVW_PTCPTN_SE_CD ),'-') AS INTRVW_PTCPTN_STTS -- 면접참여상태 ,NVL((SELECT CMMNS_CD_VALUE_NM FROM SAC100 /* 공통코드 값 */ WHERE CMMNS_CD_ID = 'APLY_RCPT_SRNG_PRGRS_STTS_SE_CD' AND CMMNS_CD_VALUE = T02.SRNG_RESULT_SE_CD ),'-') AS SRNG_INTRVW_RESULT -- 심사(면접)결과 ,NVL((SELECT CMMNS_CD_VALUE_NM FROM SAC100 /* 공통코드 값 */ WHERE CMMNS_CD_ID = 'INTRVW_PLACE_VST_MTHD_SE_CD' AND CMMNS_CD_VALUE = T.INTRVW_PLACE_VST_MTHD_SE_CD ),'-') AS INTRVW_PLACE_VST -- 면접장소방문방법 ,NVL(TO_CHAR(T.YNGBGS_SCORE),'-') AS YNGBGS_SCORE -- 청소년접수 ,NVL(TO_CHAR(T.PRTCR_SCORE),'-') AS PRTCR_SCORE -- 보호자점수 ,NVL(TO_CHAR(T.YNGBGS_SCORE + T.PRTCR_SCORE),'-') AS SRNG_INTRVW_SCORE -- 심사면접총점 ,NVL(TO_CHAR(RANK() OVER (PARTITION BY T.SRVC_EXCN_BIZ_NO ORDER BY NVL(T.YNGBGS_SCORE + T.PRTCR_SCORE,0) DESC )),'-') AS SRNG_INTRVW_RANK -- 심사면접순위 ,NVL((SELECT CMMNS_CD_VALUE_NM FROM SAC100 /* 공통코드 값 */ WHERE CMMNS_CD_ID = 'APLY_RCPT_SRNG_PRGRS_STTS_SE_CD' AND CMMNS_CD_VALUE = T02.LAST_RESULT_SE_CD ),'-') AS LAST_RESULT -- 최종결과 ,NVL((SELECT CMMNS_CD_VALUE_NM FROM SAC100 /* 공통코드 값 */ WHERE CMMNS_CD_ID = 'PAPERS_SBMSN_SE_CD' AND CMMNS_CD_VALUE = T.PAPERS_SBMSN_SE_CD ),'-') AS PAPERS_SBMSN_YN -- 서류제출여부 ,NVL(T.SPLMNT_PAPERS_NM,'-') AS SPLMNT_PAPERS_NM -- 보완서류명
,T.SRVC_EXCN_BIZ_NO -- 서비스실행사업번호 ,T.RSFR_INST_NO -- 자원제공기관번호 ,T.INTRVW_PTCPTN_SE_CD -- 면접참여구분코드 ,T.INTRVW_PTCPTN_MTHD_SE_CD -- 면접참여방법구분코드 ,T.APLY_RCPT_SRNG_PRGRS_STTS_SE_CD -- 신청접수심사진행상태구분코드 ,T5.BIZ_YR -- 사업연도 ,T1.SXDC_SE_CD AS SXDC_SE_CD -- 성별구분코드 ,T3.ACBG_SE_CD ,T02.PAPERS_RESULT_SE_CD -- 서류결과구분코드 ,T02.SRNG_RESULT_SE_CD -- 심사결과구분코드 ,T02.LAST_RESULT_SE_CD -- 최종결과구분코드 ,CASE WHEN T7.CASE_MNG_NO IS NOT NULL THEN '예' ELSE '아니요' END AS CASE_TRPR_YN -- 사례대상자 선정 여부 ,T1.UNT_TASKWK_SE_CD -- 단위업무구분코드
FROM AFA100 T LEFT JOIN SEA200 T1 /* 대상자정보 */ ON T1.TRPR_INFO_NO = T.TRPR_INFO_NO -- 대상자정보번호 LEFT JOIN (SELECT A.* ,ROW_NUMBER() OVER(PARTITION BY A.TRPR_INFO_NO ORDER BY B.ADDTNG_MNG_VALUE1 DESC, A.MNG_SN DESC) AS RN FROM SEA230 A /* 학력상태 */ LEFT JOIN SAC100 B /* 공통코드 */ ON B.CMMNS_CD_ID = 'ACBG_SE_CD' AND B.CMMNS_CD_VALUE = A.ACBG_SE_CD WHERE A.DEL_YN != 'Y' ) T3 ON T3.RN = 1 AND T3.TRPR_INFO_NO = T.TRPR_INFO_NO LEFT JOIN SDA420 T4 ON T4.SRVC_EXCN_BIZ_NO = T.SRVC_EXCN_BIZ_NO LEFT JOIN SDA400 T5 ON T5.SRVC_BIZ_NO = T4.SRVC_BIZ_NO LEFT JOIN SAA000 T6 ON T6.INST_NO = T.RSFR_INST_NO LEFT JOIN SEB100 T7 ON T7.TRPR_INFO_NO = T1.TRPR_INFO_NO AND T7.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} LEFT JOIN (SELECT T1.TRPR_INFO_NO AS TRPR_INFO_NO -- 대상자정보번호 ,T1.APLY_RCPT_SN AS APLY_RCPT_SN -- 신청접수일련번호 ,CASE WHEN T1.ANXIET_TROBL >= 90 THEN 90 - T1.ANXIET_TROBL WHEN T1.ANXIET_TROBL < 60 THEN T1.ANXIET_TROBL - 60 ELSE T1.ANXIET_TROBL END + CASE WHEN T1.PANIC >= 90 THEN 90 - T1.PANIC WHEN T1.PANIC < 60 THEN T1.PANIC - 60 ELSE T1.PANIC END + CASE WHEN T1.PTSD >= 90 THEN 90 - T1.PTSD WHEN T1.PTSD < 60 THEN T1.PTSD - 60 ELSE T1.PTSD END + CASE WHEN T1.MAIN_DEPRES >= 90 THEN 90 - T1.MAIN_DEPRES WHEN T1.MAIN_DEPRES < 60 THEN T1.MAIN_DEPRES - 60 ELSE T1.MAIN_DEPRES END + CASE WHEN T1.RAGE_CTRL >= 90 THEN 90 - T1.RAGE_CTRL WHEN T1.RAGE_CTRL < 60 THEN T1.RAGE_CTRL - 60 ELSE T1.RAGE_CTRL END + CASE WHEN T1.DMGE_THINK >= 70 THEN 0 ELSE T1.DMGE_THINK END + CASE WHEN T1.SMTIZN >= 90 THEN 90 - T1.SMTIZN WHEN T1.SMTIZN < 60 THEN T1.SMTIZN - 60 ELSE T1.SMTIZN END + CASE WHEN T1.ADDC_INTERN >= 90 THEN 90 - T1.ADDC_INTERN WHEN T1.ADDC_INTERN < 60 THEN T1.ADDC_INTERN - 60 ELSE T1.ADDC_INTERN END AS INTERN_SCORE -- 내재화 점수 ,CASE WHEN T2.OTHERS_ATCK >= 90 THEN 90 - T2.OTHERS_ATCK WHEN T2.OTHERS_ATCK < 60 THEN T2.OTHERS_ATCK - 60 ELSE T2.OTHERS_ATCK END + CASE WHEN T2.SELF_ATCK >= 90 THEN 90 - T2.SELF_ATCK WHEN T2.SELF_ATCK < 60 THEN T2.SELF_ATCK - 60 ELSE T2.SELF_ATCK END + CASE WHEN T2.AVOID >= 90 THEN 90 - T2.AVOID WHEN T2.AVOID < 60 THEN T2.AVOID - 60 ELSE T2.AVOID END + CASE WHEN T2.CMMND_NFLFL >= 90 THEN 90 - T2.CMMND_NFLFL WHEN T2.CMMND_NFLFL < 60 THEN T2.CMMND_NFLFL - 60 ELSE T2.CMMND_NFLFL END + CASE WHEN T2.ADDC_EXTERN >= 90 THEN 90 - T2.ADDC_EXTERN WHEN T2.ADDC_EXTERN < 60 THEN T2.ADDC_EXTERN - 60 ELSE T2.ADDC_EXTERN END + CASE WHEN T2.STEAL >= 90 THEN 90 - T2.STEAL WHEN T2.STEAL < 60 THEN T2.STEAL - 60 ELSE T2.STEAL END + CASE WHEN T2.GENDER_PROBM >= 90 THEN 90 - T2.GENDER_PROBM WHEN T2.GENDER_PROBM < 60 THEN T2.GENDER_PROBM - 60 ELSE T2.GENDER_PROBM END AS EXTERN_SCORE -- 외현화 점수 ,T3.SINCERITY_EVL -- 정성평가 점수 FROM (SELECT T.TRPR_INFO_NO AS TRPR_INFO_NO -- 대상자정보번호 ,T.APLY_RCPT_SN AS APLY_RCPT_SN -- 신청접수일련번호 ,MAX(CASE TRIM(T2.QUSTNB_GRDNG_RELM_ESNTAL_NM) WHEN TRIM('범불안장애') THEN T1.GRDNG_SCORE END) AS ANXIET_TROBL -- 범불안장애점수[SG2023013000118] ,MAX(CASE TRIM(T2.QUSTNB_GRDNG_RELM_ESNTAL_NM) WHEN TRIM('공황발작 ') THEN T1.GRDNG_SCORE END) AS PANIC -- 공황발작점수[SG2023013000119] ,MAX(CASE TRIM(T2.QUSTNB_GRDNG_RELM_ESNTAL_NM) WHEN TRIM('PTSD ') THEN T1.GRDNG_SCORE END) AS PTSD -- PTSD점수[SG2023013000120] ,MAX(CASE TRIM(T2.QUSTNB_GRDNG_RELM_ESNTAL_NM) WHEN TRIM('우울조절 ') THEN T1.GRDNG_SCORE END) AS MAIN_DEPRES -- 주요우울점수[SG2023013000121] ,MAX(CASE TRIM(T2.QUSTNB_GRDNG_RELM_ESNTAL_NM) WHEN TRIM('분노조절 ') THEN T1.GRDNG_SCORE END) AS RAGE_CTRL -- 분노조절점수[SG2023013000122] ,MAX(CASE TRIM(T2.QUSTNB_GRDNG_RELM_ESNTAL_NM) WHEN TRIM('피해사고 ') THEN T1.GRDNG_SCORE END) AS DMGE_THINK -- 피해사고점수[SG2023013000123] ,MAX(CASE TRIM(T2.QUSTNB_GRDNG_RELM_ESNTAL_NM) WHEN TRIM('신체화 ') THEN T1.GRDNG_SCORE END) AS SMTIZN -- 신체화점수[SG2023013000124] ,MAX(CASE TRIM(T2.QUSTNB_GRDNG_RELM_ESNTAL_NM) WHEN TRIM('중독 ') THEN T1.GRDNG_SCORE END) AS ADDC_INTERN -- 중독(내재화)점수[SG2023013000125] FROM (SELECT A.* ,ROW_NUMBER() OVER (PARTITION BY A.QUSTNB_TMPT_MNG_NO, A.TRPR_INFO_NO, A.APLY_RCPT_SN ORDER BY A.REG_YMD DESC, A.MNG_SN DESC) AS RN FROM SBB600 A /* 설문지발송이력 - 청소년사전설문지 */ INNER JOIN SAC100 B /* 공통코드값 */ ON B.ADDTNG_MNG_VALUE1 = A.QUSTNB_TMPT_MNG_NO AND B.CMMNS_CD_ID = 'QUSTNB_KND_SE_CD' AND B.CMMNS_CD_VALUE = '004' WHERE A.SRVY_ERA_SE_CD = '01' ) T LEFT JOIN SBB510 T1 ON T1.QUSTNB_TMPT_MNG_NO = T.QUSTNB_TMPT_MNG_NO AND T1.QUSTNB_MNG_NO = T.QUSTNB_MNG_NO JOIN SBB130 T2 ON T2.QUSTNB_MNG_NO = T1.QUSTNB_MNG_NO AND T2.QUSTNB_TMPT_MNG_NO = T1.QUSTNB_TMPT_MNG_NO AND T2.QUSTNB_GRDNG_RELM_MNG_NO = T1.QUSTNB_GRDNG_RELM_MNG_NO WHERE T.RN = 1 GROUP BY T.TRPR_INFO_NO, T.APLY_RCPT_SN, T.QUSTNB_TMPT_MNG_NO, T.QUSTNB_MNG_NO ) T1 LEFT JOIN (SELECT T.TRPR_INFO_NO AS TRPR_INFO_NO -- 대상자정보번호 ,T.APLY_RCPT_SN AS APLY_RCPT_SN -- 신청접수일련번호 ,MAX(CASE TRIM(T2.QUSTNB_GRDNG_RELM_ESNTAL_NM) WHEN TRIM('타인공격') THEN T1.GRDNG_SCORE END) AS OTHERS_ATCK -- 타인공격점수[SG2023013000144] ,MAX(CASE TRIM(T2.QUSTNB_GRDNG_RELM_ESNTAL_NM) WHEN TRIM('자기공격') THEN T1.GRDNG_SCORE END) AS SELF_ATCK -- 자기공격점수[SG2023013000145] ,MAX(CASE TRIM(T2.QUSTNB_GRDNG_RELM_ESNTAL_NM) WHEN TRIM('회피/퇴행') THEN T1.GRDNG_SCORE END) AS AVOID -- 회피/퇴행점수[SG2023013000146] ,MAX(CASE TRIM(T2.QUSTNB_GRDNG_RELM_ESNTAL_NM) WHEN TRIM('규범/지시 불이행') THEN T1.GRDNG_SCORE END) AS CMMND_NFLFL -- 규범/지시 불이행행점수[SG2023013000147] ,MAX(CASE TRIM(T2.QUSTNB_GRDNG_RELM_ESNTAL_NM) WHEN TRIM('중독') THEN T1.GRDNG_SCORE END) AS ADDC_EXTERN -- 중독(외현화)점수[SG2023013000148] ,MAX(CASE TRIM(T2.QUSTNB_GRDNG_RELM_ESNTAL_NM) WHEN TRIM('기타 문제행동-훔치기') THEN T1.GRDNG_SCORE END) AS STEAL -- 훔치기점수[SG2023013000149] ,MAX(CASE TRIM(T2.QUSTNB_GRDNG_RELM_ESNTAL_NM) WHEN TRIM('기타 문제행동-성문제') THEN T1.GRDNG_SCORE END) AS GENDER_PROBM -- 성문제점수[SG2023013000150] FROM (SELECT A.* ,ROW_NUMBER() OVER (PARTITION BY A.QUSTNB_TMPT_MNG_NO, A.TRPR_INFO_NO, A.APLY_RCPT_SN ORDER BY A.REG_YMD DESC, A.MNG_SN DESC) AS RN FROM SBB600 A /* 설문지발송이력 - 청소년사전설문지 */ INNER JOIN SAC100 B /* 공통코드값 */ ON B.ADDTNG_MNG_VALUE1 = A.QUSTNB_TMPT_MNG_NO AND B.CMMNS_CD_ID = 'QUSTNB_KND_SE_CD' AND B.CMMNS_CD_VALUE = '005' WHERE A.SRVY_ERA_SE_CD = '01' ) T LEFT JOIN SBB510 T1 ON T1.QUSTNB_TMPT_MNG_NO = T.QUSTNB_TMPT_MNG_NO AND T1.QUSTNB_MNG_NO = T.QUSTNB_MNG_NO JOIN SBB130 T2 ON T2.QUSTNB_MNG_NO = T1.QUSTNB_MNG_NO AND T2.QUSTNB_TMPT_MNG_NO = T1.QUSTNB_TMPT_MNG_NO AND T2.QUSTNB_GRDNG_RELM_MNG_NO = T1.QUSTNB_GRDNG_RELM_MNG_NO WHERE T.RN = 1 GROUP BY T.TRPR_INFO_NO, T.APLY_RCPT_SN, T.QUSTNB_TMPT_MNG_NO, T.QUSTNB_MNG_NO ) T2 ON T2.TRPR_INFO_NO = T1.TRPR_INFO_NO AND T2.APLY_RCPT_SN = T1.APLY_RCPT_SN LEFT JOIN (SELECT T.TRPR_INFO_NO AS TRPR_INFO_NO -- 대상자정보번호 ,T.APLY_RCPT_SN AS APLY_RCPT_SN -- 신청접수일련번호 ,SUM(GRDNG_SCORE) AS SINCERITY_EVL -- 정성평가 점수 FROM (SELECT A.* ,ROW_NUMBER() OVER (PARTITION BY A.QUSTNB_TMPT_MNG_NO, A.TRPR_INFO_NO, A.APLY_RCPT_SN ORDER BY A.REG_YMD DESC, A.MNG_SN DESC) AS RN FROM SBB600 A /* 설문지발송이력 - 보호자정성평가 */ INNER JOIN SAC100 B /* 공통코드값 */ ON B.ADDTNG_MNG_VALUE1 = A.QUSTNB_TMPT_MNG_NO AND B.CMMNS_CD_ID = 'QUSTNB_KND_SE_CD' AND B.CMMNS_CD_VALUE = '006' WHERE A.SRVY_ERA_SE_CD = '01' ) T LEFT JOIN (SELECT A.* ,ROW_NUMBER() OVER (PARTITION BY A.QUSTNB_MNG_NO, A.SRVY_RSPNS_MNG_NO, A.QUSTNB_TMPT_MNG_NO, A.QUSTNB_GRDNG_RELM_MNG_NO ORDER BY A.GRDNG_RESULT_MNG_NO DESC) AS RN FROM SBB510 A /* 채점결과 */ ) T1 ON T1.QUSTNB_TMPT_MNG_NO = T.QUSTNB_TMPT_MNG_NO AND T1.QUSTNB_MNG_NO = T.QUSTNB_MNG_NO AND T1.RN = 1 WHERE T.RN = 1 GROUP BY T.TRPR_INFO_NO, T.APLY_RCPT_SN, T.QUSTNB_TMPT_MNG_NO, T.QUSTNB_MNG_NO ) T3 ON T3.TRPR_INFO_NO = T1.TRPR_INFO_NO AND T3.APLY_RCPT_SN = T1.APLY_RCPT_SN ) T01 ON T01.TRPR_INFO_NO = T.TRPR_INFO_NO AND T01.APLY_RCPT_SN = T.APLY_RCPT_SN LEFT JOIN (SELECT TRPR_INFO_NO ,APLY_RCPT_SN ,MAX(CASE APLY_RCPT_SRNG_SE_CD WHEN '01' THEN FRST_REG_DT END) AS TPRI_APLY_YMD ,MAX(CASE APLY_RCPT_SRNG_SE_CD WHEN '03' THEN FRST_REG_DT END) AS SCD_APLY_YMD ,MAX(CASE APLY_RCPT_SRNG_SE_CD WHEN '01' THEN APLY_RCPT_SRNG_PRGRS_STTS_SE_CD END) AS APLY_STTS_SE_CD ,MAX(CASE APLY_RCPT_SRNG_SE_CD WHEN '02' THEN APLY_RCPT_SRNG_PRGRS_STTS_SE_CD END) AS APLY_RVW_SE_CD ,MAX(CASE APLY_RCPT_SRNG_SE_CD WHEN '03' THEN APLY_RCPT_SRNG_PRGRS_STTS_SE_CD END) AS STG2_APLY_STTS_SE_CD ,MAX(CASE APLY_RCPT_SRNG_SE_CD WHEN '04' THEN APLY_RCPT_SRNG_PRGRS_STTS_SE_CD END) AS PAPERS_RESULT_SE_CD ,MAX(CASE APLY_RCPT_SRNG_SE_CD WHEN '05' THEN APLY_RCPT_SRNG_PRGRS_STTS_SE_CD END) AS SRNG_RESULT_SE_CD ,MAX(CASE APLY_RCPT_SRNG_SE_CD WHEN '06' THEN APLY_RCPT_SRNG_PRGRS_STTS_SE_CD END) AS LAST_RESULT_SE_CD FROM AFA150 GROUP BY TRPR_INFO_NO, APLY_RCPT_SN )T02 ON T02.TRPR_INFO_NO = T.TRPR_INFO_NO AND T02.APLY_RCPT_SN = T.APLY_RCPT_SN ) T
WHERE 1=1 AND T.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD}
/* 기관번호 */ AND T.RSFR_INST_NO = #{INST_NO}
/* 등록일자 */ AND TO_CHAR(T.FRST_REG_DT,'YYYYMMDD') BETWEEN #{BGNG_YMD} AND #{END_YMD}
/* 대상자명[암호화] */ AND T.TRPR_NM = #{TRPR_NM}
/* 진행단계구분코드 */ AND SUBSTR(T.APLY_RCPT_SRNG_PRGRS_STTS_SE_CD,0,2) = #{PRGRS_STEP_SE_CD}
/* 진행단계상태구분코드 */ AND T.APLY_RCPT_SRNG_PRGRS_STTS_SE_CD = #{PRGRS_STEP_STTS_SE_CD}
/* 사업연도 */ AND T.BIZ_YR = #{BIZ_YR}
/* 서비스실행사업번호 */ AND T.SRVC_EXCN_BIZ_NO = #{SRVC_EXCN_BIZ_NO}
/* 성별구분코드 */ AND T.SXDC_SE_CD = #{SXDC_SE_CD}
/* 학력구분코드 */ AND T.ACBG_SE_CD = #{ACBG_SE_CD}
/* 만 나이 */ AND T.AGEA = #{AGEA}
/* 서류결과구분코드 */ AND T.PAPERS_RESULT_SE_CD = #{PAPERS_RESULT_SE_CD}
/* 면접결과구분코드 */ AND T.INTRVW_PTCPTN_MTHD_SE_CD = #{INTRVW_PTCPTN_MTHD_SE_CD}
/* 면접참여구분코드 */ AND T.INTRVW_PTCPTN_SE_CD = #{INTRVW_PTCPTN_SE_CD}
/* 심사결과구분코드 */ AND T.SRNG_RESULT_SE_CD = #{SRNG_RESULT_SE_CD}
/* 심사면접점수(이상) */ AND T.SRNG_INTRVW_SCORE >= #{GRDNG_SCORE}
/* 심사면접점수(같음) */ AND T.SRNG_INTRVW_SCORE = #{GRDNG_SCORE}
/* 심사면접점수(이하) */ AND T.SRNG_INTRVW_SCORE <= #{GRDNG_SCORE}
/* 최종결과구분코드 */ AND T.LAST_RESULT_SE_CD = #{LAST_RESULT_SE_CD}
/* 심사면접순위 */ AND T.SRNG_INTRVW_RANK <= #{SLCTN_RANK}
/* 입교신청(1차) & 입소신청 */ AND SUBSTR(T.APLY_RCPT_SRNG_PRGRS_STTS_SE_CD,0,2) <= '02'
/* 입교신청(2차) */ AND (SUBSTR(T.APLY_RCPT_SRNG_PRGRS_STTS_SE_CD,0,2) > '02' AND SUBSTR(T.APLY_RCPT_SRNG_PRGRS_STTS_SE_CD,0,2) <= '04' OR T.APLY_RCPT_SRNG_PRGRS_STTS_SE_CD = '0203')
/* 입교접수 & 입소접수 */ AND (SUBSTR(T.APLY_RCPT_SRNG_PRGRS_STTS_SE_CD,0,2) > '04' OR T.APLY_RCPT_SRNG_PRGRS_STTS_SE_CD = '0401')
ORDER BY T.FRST_REG_DT DESC

