/*SQL-ID : isry.csemd.mngrpage.aplcnttrprmng.mapper.AplcntTrprMngMapper selectSrvyRspnsList : SBB500 설문응답 조회*/
SELECT A.INST_NO , A.QUSTNB_TMPT_MNG_NO , A.QUSTNB_MNG_NO , (SELECT SUM(GRDNG_SCORE) FROM SBB510 WHERE QUSTNB_TMPT_MNG_NO = A.QUSTNB_TMPT_MNG_NO AND QUSTNB_MNG_NO = A.QUSTNB_MNG_NO) AS GRDNG_SCORE , TO_CHAR(B.RSPNS_DT, 'YYYY-MM-DD HH24:MI:SS') AS RSPNS_DT , CASE WHEN B.RSPNS_DT IS NOT NULL THEN '02' ELSE '01' END SRVY_WRT_STTS_SE_CD , D.CMMNS_CD_VALUE_NM , D.CMMNS_CD_VALUE , A.MSSAGE_ESNTAL_NO FROM ( SELECT * FROM ( SELECT A.INST_NO, A.QUSTNB_TMPT_MNG_NO, A.QUSTNB_MNG_NO, A.MSSAGE_ESNTAL_NO, A.MNG_SN , ROW_NUMBER() OVER (PARTITION BY A.QUSTNB_TMPT_MNG_NO ORDER BY A.FRST_REG_DT DESC) AS RN FROM (SELECT * FROM SBB600 A WHERE 1=1 AND A.TRPR_INFO_NO = #{TRPR_INFO_NO} AND A.APLY_RCPT_SN = #{APLY_RCPT_SN} AND A.INST_NO = #{INST_NO} AND A.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} ) A ) WHERE RN = 1 ) A, SBB500 B, ( SELECT CMMNS_CD_VALUE, CMMNS_CD_VALUE_NM, ADDTNG_MNG_VALUE1, SRTNG_SQNCE FROM SAC100 WHERE CMMNS_CD_ID = 'QUSTNB_KND_SE_CD' AND CMMNS_CD_VALUE IN
('004', '005', '006', '007') AND USE_YN = 'Y'
('001', '002', '003') AND USE_YN = 'Y'
) D WHERE 1=1 AND A.QUSTNB_TMPT_MNG_NO = D.ADDTNG_MNG_VALUE1 AND A.QUSTNB_MNG_NO = B.QUSTNB_MNG_NO (+) ORDER BY D.SRTNG_SQNCE

