			, MSSAGE_ESNTAL_NO            --메시지고유번호
			, RSVT_SNDNG_YN               --예약발송여부
			, RSVT_CHRCTR_SNDNG_DT        --예약문자발송일시
			, RSVT_CHRCTR_CN              --예약문자내용
			, CHRCTR_SNDNG_RTRCN_YN       --문자발송취소여부
			, DSPTCH_TRPR_NM_ENCPT        --발신대상자명암호화
