SELECT NVL(MAX(MNG_SN)+1 ,1) FROM SBB600 WHERE INST_NO = #{INST_NO} AND REG_YMD = TO_CHAR(SYSDATE, 'YYYYMMDD')
/*SQL-ID : isry.csemd.mngrpage.aplcnttrprmng.mapper.AplcntTrprMngMapper insertQustnbSndngHstr : 설문발송이력 SBB600 */
INSERT INTO SBB600 ( INST_NO /* 기관번호 */ ,REG_YMD /* 등록일자 */ ,MNG_SN /* 관리일련번호 */ ,UNT_TASKWK_SE_CD /* 단위업무구분코드 */ ,SRVC_EXCN_BIZ_NO /* 서비스실행사업번호 */ ,TRPR_INFO_NO /* 대상자정보번호 */ ,APLY_RCPT_SN /* 신청접수일련번호 */ ,TRPR_REL_SE_CD /* 대상자관계구분코드 */ ,QUSTNB_MNG_NO /* 설문지관리번호 */ ,QUSTNB_TMPT_MNG_NO /* 설문지템플릿관리번호 */ ,SRVY_ERA_SE_CD /* 설문시기구분코드 */ ,NO_INPT_SNDNG_YN /* 번호입력발송여부 */ ,SRVY_RSPDNT_NM_ENCPT /* 설문응답자명암호화 */ ,SRVY_RSPNS_RCPTN_MBL_TELNO_ENCPT /* 설문응답수신휴대전화번호암호화 */ ,RSVT_SNDNG_YN /* 예약발송여부 */ ,SNDNG_DT /* 발송일시 */ ,CHRCTR_CN /* 문자내용 */ ,MSSAGE_ESNTAL_NO /* 메세지고유번호 */ ,SRVY_RCPTN_MTHD_SE_CD /* 설문방법구분코드*/ ,FRST_RGTR_ID /* 최초등록자아이디 */ ,FRST_REG_DT /* 최초등록일시 */ ,LAST_MDFR_ID /* 최종수정자아이디 */ ,LAST_MDFCN_DT /* 최종수정일시 */ ) VALUES ( #{INST_NO}, /* 기관번호 */ TO_CHAR(SYSDATE, 'YYYYMMDD'), /* 등록일자 */ #{MNG_SN}, /* 관리일련번호 */ #{UNT_TASKWK_SE_CD}, /* 단위업무구분코드 */ #{SRVC_EXCN_BIZ_NO}, /* 서비스실행사업번호 */ #{TRPR_INFO_NO}, /* 대상자정보번호 */ #{APLY_RCPT_SN}, /* 신청접수일련번호 */ #{TRPR_REL_SE_CD}, /* 대상자관계구분코드 */ #{QUSTNB_MNG_NO}, /* 설문지관리번호 */ #{QUSTNB_TMPT_MNG_NO}, /* 설문지템플릿관리번호 */ #{SRVY_ERA_SE_CD}, /* 설문시기구분코드 */ #{NO_INPT_SNDNG_YN}, /* 번호입력발송여부 */ ENC_B64(#{SRVY_RSPDNT_NM_ENCPT}), /* 설문응답자명암호화 */ ENC_B64(#{SRVY_RSPNS_RCPTN_MBL_TELNO_ENCPT}), /* 설문응답수신휴대전화번호암호화 */ #{RSVT_SNDNG_YN}, /* 예약발송여부 */ SYSDATE, /* 발송일시 */ #{CHRCTR_CN}, /* 문자내용 */ #{MSSAGE_ESNTAL_NO} /* 메세지고유번호 */ , #{SRVY_RCPTN_MTHD_SE_CD} /*설문방법구분코드*/ , #{FRST_RGTR_ID}, /* 최초등록자아이디 */ SYSDATE, /* 최초등록일시 */ #{LAST_MDFR_ID}, /* 최종수정자아이디 */ SYSDATE /* 최종수정일시 */ )

mapper.select:
/* isry.csemd.mngrpage.aplcnttrprmng.mapper.AplcntTrprMngMapper - selectPapersScrennList */ /* 서류스크리닝 조회 - Lee SangHoon */ SELECT * FROM (SELECT X.* ,X.INTERN_SUBTOT*0.47 + X.EXTERN_SUBTOT*0.23 + X.SINCERITY_EVL AS PAPERS_TOTAL_SCORE -- 서류총점 ,RANK() OVER(PARTITION BY X.SRVC_EXCN_BIZ_NO ORDER BY NVL(X.INTERN_SUBTOT*0.47 + X.EXTERN_SUBTOT*0.23 + X.SINCERITY_EVL,0) DESC) AS PAPERS_SRNG_RANK -- 서류심사순위 ,X.INTERN_SUBTOT*0.47 AS INTERN_SCORE -- 내재화점수 ,X.EXTERN_SUBTOT*0.23 AS EXTERN_SCORE -- 외현화점수 FROM (SELECT A.* ,C.ACBG_SE_NM -- 학력 ,CASE (SELECT COUNT(*) FROM SEA240 WHERE TRPR_INFO_NO = A.TRPR_INFO_NO OR INDV_IDNTFC_NO = B.INDV_IDNTFC_NO) WHEN 0 THEN 'X' ELSE 'O' END AS SCHULW_DSCNTC_YN -- 학업중단여부 ,CASE WHEN A.ANXIET_TROBL >= 90 THEN 90 - A.ANXIET_TROBL WHEN A.ANXIET_TROBL < 60 THEN A.ANXIET_TROBL - 60 ELSE A.ANXIET_TROBL END + CASE WHEN A.PANIC >= 90 THEN 90 - A.PANIC WHEN A.PANIC < 60 THEN A.PANIC - 60 ELSE A.PANIC END + CASE WHEN A.PTSD >= 90 THEN 90 - A.PTSD WHEN A.PTSD < 60 THEN A.PTSD - 60 ELSE A.PTSD END + CASE WHEN A.MAIN_DEPRES >= 90 THEN 90 - A.MAIN_DEPRES WHEN A.MAIN_DEPRES < 60 THEN A.MAIN_DEPRES - 60 ELSE A.MAIN_DEPRES END + CASE WHEN A.RAGE_CTRL >= 90 THEN 90 - A.RAGE_CTRL WHEN A.RAGE_CTRL < 60 THEN A.RAGE_CTRL - 60 ELSE A.RAGE_CTRL END + CASE WHEN A.DMGE_THINK >= 70 THEN 0 ELSE A.DMGE_THINK END + CASE WHEN A.SMTIZN >= 90 THEN 90 - A.SMTIZN WHEN A.SMTIZN < 60 THEN A.SMTIZN - 60 ELSE A.SMTIZN END + CASE WHEN A.ADDC_INTERN >= 90 THEN 90 - A.ADDC_INTERN WHEN A.ADDC_INTERN < 60 THEN A.ADDC_INTERN - 60 ELSE A.ADDC_INTERN END AS INTERN_SUBTOT -- 내재화 소계 ,CASE WHEN A.OTHERS_ATCK >= 90 THEN 90 - A.OTHERS_ATCK WHEN A.OTHERS_ATCK < 60 THEN A.OTHERS_ATCK - 60 ELSE A.OTHERS_ATCK END + CASE WHEN A.SELF_ATCK >= 90 THEN 90 - A.SELF_ATCK WHEN A.SELF_ATCK < 60 THEN A.SELF_ATCK - 60 ELSE A.SELF_ATCK END + CASE WHEN A.AVOID >= 90 THEN 90 - A.AVOID WHEN A.AVOID < 60 THEN A.AVOID - 60 ELSE A.AVOID END + CASE WHEN A.CMMND_NFLFL >= 90 THEN 90 - A.CMMND_NFLFL WHEN A.CMMND_NFLFL < 60 THEN A.CMMND_NFLFL - 60 ELSE A.CMMND_NFLFL END + CASE WHEN A.ADDC_EXTERN >= 90 THEN 90 - A.ADDC_EXTERN WHEN A.ADDC_EXTERN < 60 THEN A.ADDC_EXTERN - 60 ELSE A.ADDC_EXTERN END + CASE WHEN A.STEAL >= 90 THEN 90 - A.STEAL WHEN A.STEAL < 60 THEN A.STEAL - 60 ELSE A.STEAL END + CASE WHEN A.GENDER_PROBM >= 90 THEN 90 - A.GENDER_PROBM WHEN A.GENDER_PROBM < 60 THEN A.GENDER_PROBM - 60 ELSE A.GENDER_PROBM END AS EXTERN_SUBTOT -- 외현화 소계 FROM (SELECT CASE( SELECT F.SRVY_QESITM_EXMPL_MNG_NO FROM SBB100 A LEFT JOIN SBB500 D ON D.QUSTNB_MNG_NO = A.QUSTNB_MNG_NO AND D.SRVY_RSPNS_MNG_NO = (SELECT MAX(SRVY_RSPNS_MNG_NO) FROM SBB500 WHERE QUSTNB_MNG_NO = A.QUSTNB_MNG_NO) LEFT JOIN SBB220 E ON E.SRVY_RSPNS_MNG_NO = D.SRVY_RSPNS_MNG_NO LEFT JOIN SBB210 F ON F.QESITM_MNG_NO = E.QESITM_MNG_NO AND F.SRVY_QESITM_EXMPL_SCORE = E.QESITM_SINGL_RSPNS_VALUE WHERE A.QUSTNB_MNG_NO = T3.QUSTNB_MNG_NO AND E.QESITM_MNG_NO = 'QN2022103100013' ) WHEN 'QE2022103100021' THEN 'Y' ELSE 'N' END AS PRTCTN_OBSERV_YN -- 보호관찰여부 ,CASE( SELECT F.SRVY_QESITM_EXMPL_MNG_NO FROM SBB100 A LEFT JOIN SBB500 D ON D.QUSTNB_MNG_NO = A.QUSTNB_MNG_NO AND D.SRVY_RSPNS_MNG_NO = (SELECT MAX(SRVY_RSPNS_MNG_NO) FROM SBB500 WHERE QUSTNB_MNG_NO = A.QUSTNB_MNG_NO) LEFT JOIN SBB220 E ON E.SRVY_RSPNS_MNG_NO = D.SRVY_RSPNS_MNG_NO LEFT JOIN SBB210 F ON F.QESITM_MNG_NO = E.QESITM_MNG_NO AND F.SRVY_QESITM_EXMPL_SCORE = E.QESITM_SINGL_RSPNS_VALUE WHERE A.QUSTNB_MNG_NO = T3.QUSTNB_MNG_NO AND E.QESITM_MNG_NO = 'QN2022103100015' ) WHEN 'QE2022103100023' THEN 'Y' ELSE 'N' END AS TRIAL_PRGRS_YN -- 재판진행여부 ,CASE( SELECT F.SRVY_QESITM_EXMPL_MNG_NO FROM SBB100 A LEFT JOIN SBB500 D ON D.QUSTNB_MNG_NO = A.QUSTNB_MNG_NO AND D.SRVY_RSPNS_MNG_NO = (SELECT MAX(SRVY_RSPNS_MNG_NO) FROM SBB500 WHERE QUSTNB_MNG_NO = A.QUSTNB_MNG_NO) LEFT JOIN SBB220 E ON E.SRVY_RSPNS_MNG_NO = D.SRVY_RSPNS_MNG_NO LEFT JOIN SBB210 F ON F.QESITM_MNG_NO = E.QESITM_MNG_NO AND F.SRVY_QESITM_EXMPL_SCORE = E.QESITM_SINGL_RSPNS_VALUE WHERE A.QUSTNB_MNG_NO = T3.QUSTNB_MNG_NO AND E.QESITM_MNG_NO = 'QN2022103100017' ) WHEN 'QE2022103100025' THEN 'Y' ELSE 'N' END AS SCHL_VIOLNC_YN -- 학교폭력여부 ,CASE( SELECT F.SRVY_QESITM_EXMPL_MNG_NO FROM SBB100 A LEFT JOIN SBB500 D ON D.QUSTNB_MNG_NO = A.QUSTNB_MNG_NO AND D.SRVY_RSPNS_MNG_NO = (SELECT MAX(SRVY_RSPNS_MNG_NO) FROM SBB500 WHERE QUSTNB_MNG_NO = A.QUSTNB_MNG_NO) LEFT JOIN SBB220 E ON E.SRVY_RSPNS_MNG_NO = D.SRVY_RSPNS_MNG_NO LEFT JOIN SBB210 F ON F.QESITM_MNG_NO = E.QESITM_MNG_NO AND F.SRVY_QESITM_EXMPL_SCORE = E.QESITM_SINGL_RSPNS_VALUE WHERE A.QUSTNB_MNG_NO = T3.QUSTNB_MNG_NO AND E.QESITM_MNG_NO = 'QN2022103100019' ) WHEN 'QE2022103100027' THEN 'Y' ELSE 'N' END AS POLC_EXMN_YN -- 경찰조사여부 ,CASE( SELECT F.SRVY_QESITM_EXMPL_MNG_NO FROM SBB100 A LEFT JOIN SBB500 D ON D.QUSTNB_MNG_NO = A.QUSTNB_MNG_NO AND D.SRVY_RSPNS_MNG_NO = (SELECT MAX(SRVY_RSPNS_MNG_NO) FROM SBB500 WHERE QUSTNB_MNG_NO = A.QUSTNB_MNG_NO) LEFT JOIN SBB220 E ON E.SRVY_RSPNS_MNG_NO = D.SRVY_RSPNS_MNG_NO LEFT JOIN SBB210 F ON F.QESITM_MNG_NO = E.QESITM_MNG_NO AND F.SRVY_QESITM_EXMPL_SCORE = E.QESITM_SINGL_RSPNS_VALUE WHERE A.QUSTNB_MNG_NO = T3.QUSTNB_MNG_NO AND E.QESITM_MNG_NO = 'QN2022103100021' ) WHEN 'QE2022103100029' THEN 'Y' ELSE 'N' END AS RLVT_NAPC_YN -- 해당없음여부 ,CASE( SELECT F.SRVY_QESITM_EXMPL_MNG_NO FROM SBB100 A LEFT JOIN SBB500 D ON D.QUSTNB_MNG_NO = A.QUSTNB_MNG_NO AND D.SRVY_RSPNS_MNG_NO = (SELECT MAX(SRVY_RSPNS_MNG_NO) FROM SBB500 WHERE QUSTNB_MNG_NO = A.QUSTNB_MNG_NO) LEFT JOIN SBB220 E ON E.SRVY_RSPNS_MNG_NO = D.SRVY_RSPNS_MNG_NO LEFT JOIN SBB210 F ON F.QESITM_MNG_NO = E.QESITM_MNG_NO AND F.SRVY_QESITM_EXMPL_SCORE = E.QESITM_SINGL_RSPNS_VALUE WHERE A.QUSTNB_MNG_NO = T3.QUSTNB_MNG_NO AND E.QESITM_MNG_NO = 'QN2022103100022' ) WHEN 'QE2022103100031' THEN 'Y' ELSE 'N' END AS ALLERGY_YN -- 알러지여부 ,CASE( SELECT F.SRVY_QESITM_EXMPL_MNG_NO FROM SBB100 A LEFT JOIN SBB500 D ON D.QUSTNB_MNG_NO = A.QUSTNB_MNG_NO AND D.SRVY_RSPNS_MNG_NO = (SELECT MAX(SRVY_RSPNS_MNG_NO) FROM SBB500 WHERE QUSTNB_MNG_NO = A.QUSTNB_MNG_NO) LEFT JOIN SBB220 E ON E.SRVY_RSPNS_MNG_NO = D.SRVY_RSPNS_MNG_NO LEFT JOIN SBB210 F ON F.QESITM_MNG_NO = E.QESITM_MNG_NO AND F.SRVY_QESITM_EXMPL_SCORE = E.QESITM_SINGL_RSPNS_VALUE WHERE A.QUSTNB_MNG_NO = T3.QUSTNB_MNG_NO AND E.QESITM_MNG_NO = 'QN2022103100023' ) WHEN 'QE2022103100033' THEN 'Y' ELSE 'N' END AS DRFSTF_TAKNG_YN -- 약물복용여부 ,CASE( SELECT F.SRVY_QESITM_EXMPL_MNG_NO FROM SBB100 A LEFT JOIN SBB500 D ON D.QUSTNB_MNG_NO = A.QUSTNB_MNG_NO AND D.SRVY_RSPNS_MNG_NO = (SELECT MAX(SRVY_RSPNS_MNG_NO) FROM SBB500 WHERE QUSTNB_MNG_NO = A.QUSTNB_MNG_NO) LEFT JOIN SBB220 E ON E.SRVY_RSPNS_MNG_NO = D.SRVY_RSPNS_MNG_NO LEFT JOIN SBB210 F ON F.QESITM_MNG_NO = E.QESITM_MNG_NO AND F.SRVY_QESITM_EXMPL_SCORE = E.QESITM_SINGL_RSPNS_VALUE WHERE A.QUSTNB_MNG_NO = T3.QUSTNB_MNG_NO AND E.QESITM_MNG_NO = 'QN2022103100024' ) WHEN 'QE2022103100036' THEN 'N' ELSE 'Y' END AS HELP_NEED_YN -- 도움필요여부 ,( SELECT MAX(B.GRDNG_SCORE) FROM SBB510 B JOIN SBB130 C ON C.QUSTNB_MNG_NO = B.QUSTNB_MNG_NO AND C.QUSTNB_TMPT_MNG_NO = B.QUSTNB_TMPT_MNG_NO AND C.QUSTNB_GRDNG_RELM_MNG_NO = B.QUSTNB_GRDNG_RELM_MNG_NO WHERE B.QUSTNB_MNG_NO = T1.QUSTNB_MNG_NO AND TRIM(C.QUSTNB_GRDNG_RELM_ESNTAL_NM) = TRIM('범불안장애') ) AS ANXIET_TROBL -- 범불안장애점수[SG2023013000118] ,( SELECT MAX(B.GRDNG_SCORE) FROM SBB510 B JOIN SBB130 C ON C.QUSTNB_MNG_NO = B.QUSTNB_MNG_NO AND C.QUSTNB_TMPT_MNG_NO = B.QUSTNB_TMPT_MNG_NO AND C.QUSTNB_GRDNG_RELM_MNG_NO = B.QUSTNB_GRDNG_RELM_MNG_NO WHERE B.QUSTNB_MNG_NO = T1.QUSTNB_MNG_NO AND TRIM(C.QUSTNB_GRDNG_RELM_ESNTAL_NM) = TRIM('공황발작 ') ) AS PANIC -- 공황발작점수[SG2023013000119] ,( SELECT MAX(B.GRDNG_SCORE) FROM SBB510 B JOIN SBB130 C ON C.QUSTNB_MNG_NO = B.QUSTNB_MNG_NO AND C.QUSTNB_TMPT_MNG_NO = B.QUSTNB_TMPT_MNG_NO AND C.QUSTNB_GRDNG_RELM_MNG_NO = B.QUSTNB_GRDNG_RELM_MNG_NO WHERE B.QUSTNB_MNG_NO = T1.QUSTNB_MNG_NO AND TRIM(C.QUSTNB_GRDNG_RELM_ESNTAL_NM) = TRIM('PTSD ') ) AS PTSD -- PTSD점수[SG2023013000120] ,( SELECT MAX(B.GRDNG_SCORE) FROM SBB510 B JOIN SBB130 C ON C.QUSTNB_MNG_NO = B.QUSTNB_MNG_NO AND C.QUSTNB_TMPT_MNG_NO = B.QUSTNB_TMPT_MNG_NO AND C.QUSTNB_GRDNG_RELM_MNG_NO = B.QUSTNB_GRDNG_RELM_MNG_NO WHERE B.QUSTNB_MNG_NO = T1.QUSTNB_MNG_NO AND TRIM(C.QUSTNB_GRDNG_RELM_ESNTAL_NM) = TRIM('우울조절 ') ) AS MAIN_DEPRES -- 주요우울점수[SG2023013000121] ,( SELECT MAX(B.GRDNG_SCORE) FROM SBB510 B JOIN SBB130 C ON C.QUSTNB_MNG_NO = B.QUSTNB_MNG_NO AND C.QUSTNB_TMPT_MNG_NO = B.QUSTNB_TMPT_MNG_NO AND C.QUSTNB_GRDNG_RELM_MNG_NO = B.QUSTNB_GRDNG_RELM_MNG_NO WHERE B.QUSTNB_MNG_NO = T1.QUSTNB_MNG_NO AND TRIM(C.QUSTNB_GRDNG_RELM_ESNTAL_NM) = TRIM('분노조절 ') ) AS RAGE_CTRL -- 분노조절점수[SG2023013000122] ,( SELECT MAX(B.GRDNG_SCORE) FROM SBB510 B JOIN SBB130 C ON C.QUSTNB_MNG_NO = B.QUSTNB_MNG_NO AND C.QUSTNB_TMPT_MNG_NO = B.QUSTNB_TMPT_MNG_NO AND C.QUSTNB_GRDNG_RELM_MNG_NO = B.QUSTNB_GRDNG_RELM_MNG_NO WHERE B.QUSTNB_MNG_NO = T1.QUSTNB_MNG_NO AND TRIM(C.QUSTNB_GRDNG_RELM_ESNTAL_NM) = TRIM('피해사고 ') ) AS DMGE_THINK -- 피해사고점수[SG2023013000123] ,( SELECT MAX(B.GRDNG_SCORE) FROM SBB510 B JOIN SBB130 C ON C.QUSTNB_MNG_NO = B.QUSTNB_MNG_NO AND C.QUSTNB_TMPT_MNG_NO = B.QUSTNB_TMPT_MNG_NO AND C.QUSTNB_GRDNG_RELM_MNG_NO = B.QUSTNB_GRDNG_RELM_MNG_NO WHERE B.QUSTNB_MNG_NO = T1.QUSTNB_MNG_NO AND TRIM(C.QUSTNB_GRDNG_RELM_ESNTAL_NM) = TRIM('신체화 ') ) AS SMTIZN -- 신체화점수[SG2023013000124] ,( SELECT MAX(B.GRDNG_SCORE) FROM SBB510 B JOIN SBB130 C ON C.QUSTNB_MNG_NO = B.QUSTNB_MNG_NO AND C.QUSTNB_TMPT_MNG_NO = B.QUSTNB_TMPT_MNG_NO AND C.QUSTNB_GRDNG_RELM_MNG_NO = B.QUSTNB_GRDNG_RELM_MNG_NO WHERE B.QUSTNB_MNG_NO = T1.QUSTNB_MNG_NO AND TRIM(C.QUSTNB_GRDNG_RELM_ESNTAL_NM) = TRIM('중독 ') ) AS ADDC_INTERN -- 중독(내재화)점수[SG2023013000125] ,( SELECT MAX(B.GRDNG_SCORE) FROM SBB510 B JOIN SBB130 C ON C.QUSTNB_MNG_NO = B.QUSTNB_MNG_NO AND C.QUSTNB_TMPT_MNG_NO = B.QUSTNB_TMPT_MNG_NO AND C.QUSTNB_GRDNG_RELM_MNG_NO = B.QUSTNB_GRDNG_RELM_MNG_NO WHERE B.QUSTNB_MNG_NO = T2.QUSTNB_MNG_NO AND TRIM(C.QUSTNB_GRDNG_RELM_ESNTAL_NM) = TRIM('타인공격') ) AS OTHERS_ATCK -- 타인공격점수[SG2023013000144] ,( SELECT MAX(B.GRDNG_SCORE) FROM SBB510 B JOIN SBB130 C ON C.QUSTNB_MNG_NO = B.QUSTNB_MNG_NO AND C.QUSTNB_TMPT_MNG_NO = B.QUSTNB_TMPT_MNG_NO AND C.QUSTNB_GRDNG_RELM_MNG_NO = B.QUSTNB_GRDNG_RELM_MNG_NO WHERE B.QUSTNB_MNG_NO = T2.QUSTNB_MNG_NO AND TRIM(C.QUSTNB_GRDNG_RELM_ESNTAL_NM) = TRIM('자기공격') ) AS SELF_ATCK -- 자기공격점수[SG2023013000145] ,( SELECT MAX(B.GRDNG_SCORE) FROM SBB510 B JOIN SBB130 C ON C.QUSTNB_MNG_NO = B.QUSTNB_MNG_NO AND C.QUSTNB_TMPT_MNG_NO = B.QUSTNB_TMPT_MNG_NO AND C.QUSTNB_GRDNG_RELM_MNG_NO = B.QUSTNB_GRDNG_RELM_MNG_NO WHERE B.QUSTNB_MNG_NO = T2.QUSTNB_MNG_NO AND TRIM(C.QUSTNB_GRDNG_RELM_ESNTAL_NM) = TRIM('회피/퇴행') ) AS AVOID -- 회피/퇴행점수[SG2023013000146] ,( SELECT MAX(B.GRDNG_SCORE) FROM SBB510 B JOIN SBB130 C ON C.QUSTNB_MNG_NO = B.QUSTNB_MNG_NO AND C.QUSTNB_TMPT_MNG_NO = B.QUSTNB_TMPT_MNG_NO AND C.QUSTNB_GRDNG_RELM_MNG_NO = B.QUSTNB_GRDNG_RELM_MNG_NO WHERE B.QUSTNB_MNG_NO = T2.QUSTNB_MNG_NO AND TRIM(C.QUSTNB_GRDNG_RELM_ESNTAL_NM) = TRIM('규범/지시 불이행') ) AS CMMND_NFLFL -- 규범/지시 불이행행점수[SG2023013000147] ,( SELECT MAX(B.GRDNG_SCORE) FROM SBB510 B JOIN SBB130 C ON C.QUSTNB_MNG_NO = B.QUSTNB_MNG_NO AND C.QUSTNB_TMPT_MNG_NO = B.QUSTNB_TMPT_MNG_NO AND C.QUSTNB_GRDNG_RELM_MNG_NO = B.QUSTNB_GRDNG_RELM_MNG_NO WHERE B.QUSTNB_MNG_NO = T2.QUSTNB_MNG_NO AND TRIM(C.QUSTNB_GRDNG_RELM_ESNTAL_NM) = TRIM('중독') ) AS ADDC_EXTERN -- 중독(외현화)점수[SG2023013000148] ,( SELECT MAX(B.GRDNG_SCORE) FROM SBB510 B JOIN SBB130 C ON C.QUSTNB_MNG_NO = B.QUSTNB_MNG_NO AND C.QUSTNB_TMPT_MNG_NO = B.QUSTNB_TMPT_MNG_NO AND C.QUSTNB_GRDNG_RELM_MNG_NO = B.QUSTNB_GRDNG_RELM_MNG_NO WHERE B.QUSTNB_MNG_NO = T2.QUSTNB_MNG_NO AND TRIM(C.QUSTNB_GRDNG_RELM_ESNTAL_NM) = TRIM('기타 문제행동-훔치기') ) AS STEAL -- 훔치기점수[SG2023013000149] ,( SELECT MAX(B.GRDNG_SCORE) FROM SBB510 B JOIN SBB130 C ON C.QUSTNB_MNG_NO = B.QUSTNB_MNG_NO AND C.QUSTNB_TMPT_MNG_NO = B.QUSTNB_TMPT_MNG_NO AND C.QUSTNB_GRDNG_RELM_MNG_NO = B.QUSTNB_GRDNG_RELM_MNG_NO WHERE B.QUSTNB_MNG_NO = T2.QUSTNB_MNG_NO AND TRIM(C.QUSTNB_GRDNG_RELM_ESNTAL_NM) = TRIM('기타 문제행동-성문제') ) AS GENDER_PROBM -- 성문제점수[SG2023013000150] ,( SELECT SUM(GRDNG_SCORE) FROM SBB510 WHERE QUSTNB_MNG_NO = T3.QUSTNB_MNG_NO ) * 0.3 AS SINCERITY_EVL -- 정성평가 점수 ,NVL(T.HELP_DMND_CN, (SELECT D.QESITM_RSPNS_CN FROM SBB100 A LEFT JOIN SBB500 C ON C.QUSTNB_MNG_NO = A.QUSTNB_MNG_NO AND C.SRVY_RSPNS_MNG_NO = (SELECT MAX(SRVY_RSPNS_MNG_NO) FROM SBB500 WHERE QUSTNB_MNG_NO = A.QUSTNB_MNG_NO) LEFT JOIN SBB220 D ON D.SRVY_RSPNS_MNG_NO = C.SRVY_RSPNS_MNG_NO WHERE A.QUSTNB_MNG_NO = T3.QUSTNB_MNG_NO AND D.QESITM_MNG_NO = 'QN2022103100025')) AS HELP_DMND_CN -- 도움요청내용 ,NVL(T.DSCSN_EXPRNC_CN, (SELECT D.QESITM_RSPNS_CN FROM SBB100 A LEFT JOIN SBB500 C ON C.QUSTNB_MNG_NO = A.QUSTNB_MNG_NO AND C.SRVY_RSPNS_MNG_NO = (SELECT MAX(SRVY_RSPNS_MNG_NO) FROM SBB500 WHERE QUSTNB_MNG_NO = A.QUSTNB_MNG_NO) LEFT JOIN SBB220 D ON D.SRVY_RSPNS_MNG_NO = C.SRVY_RSPNS_MNG_NO WHERE A.QUSTNB_MNG_NO = T3.QUSTNB_MNG_NO AND D.QESITM_MNG_NO = 'QN2022103100026')) AS DSCSN_EXPRNC_CN -- 상담경험내용 ,NVL(T.ENTSC_MTVTN_NCSSTY_CN, (SELECT D.QESITM_RSPNS_CN FROM SBB100 A LEFT JOIN SBB500 C ON C.QUSTNB_MNG_NO = A.QUSTNB_MNG_NO AND C.SRVY_RSPNS_MNG_NO = (SELECT MAX(SRVY_RSPNS_MNG_NO) FROM SBB500 WHERE QUSTNB_MNG_NO = A.QUSTNB_MNG_NO) LEFT JOIN SBB220 D ON D.SRVY_RSPNS_MNG_NO = C.SRVY_RSPNS_MNG_NO WHERE A.QUSTNB_MNG_NO = T3.QUSTNB_MNG_NO AND D.QESITM_MNG_NO = 'QN2022103100027')) AS ENTSC_MTVTN_NCSSTY_CN -- 입교동기필요성내용
,T.TRPR_INFO_NO -- 대상자정보번호 ,T.APLY_RCPT_SN -- 신청접수일련번호 ,T.SRVC_EXCN_BIZ_NO -- 서비스실행사업번호
FROM AFA100 T /* 신청접수 */ LEFT JOIN (SELECT A.TRPR_INFO_NO, A.APLY_RCPT_SN, A.QUSTNB_TMPT_MNG_NO, A.QUSTNB_MNG_NO ,ROW_NUMBER() OVER (PARTITION BY A.QUSTNB_TMPT_MNG_NO, A.TRPR_INFO_NO, A.APLY_RCPT_SN ORDER BY A.REG_YMD DESC, A.MNG_SN DESC) AS RN FROM SBB600 A /* 설문지발송이력 - 청소년설문지 */ INNER JOIN SAC100 B /* 공통코드값 */ ON B.ADDTNG_MNG_VALUE1 = A.QUSTNB_TMPT_MNG_NO AND B.CMMNS_CD_ID = 'QUSTNB_KND_SE_CD' AND B.CMMNS_CD_VALUE = '004' WHERE A.SRVY_ERA_SE_CD = '01') T1 ON T1.RN = 1 AND T1.TRPR_INFO_NO = T.TRPR_INFO_NO AND T1.APLY_RCPT_SN = T.APLY_RCPT_SN LEFT JOIN (SELECT A.TRPR_INFO_NO, A.APLY_RCPT_SN, A.QUSTNB_TMPT_MNG_NO, A.QUSTNB_MNG_NO ,ROW_NUMBER() OVER (PARTITION BY A.QUSTNB_TMPT_MNG_NO, A.TRPR_INFO_NO, A.APLY_RCPT_SN ORDER BY A.REG_YMD DESC, A.MNG_SN DESC) AS RN FROM SBB600 A /* 설문지발송이력 - 보호자설문지 */ INNER JOIN SAC100 B /* 공통코드값 */ ON B.ADDTNG_MNG_VALUE1 = A.QUSTNB_TMPT_MNG_NO AND B.CMMNS_CD_ID = 'QUSTNB_KND_SE_CD' AND B.CMMNS_CD_VALUE = '005' WHERE A.SRVY_ERA_SE_CD = '01') T2 ON T2.RN = 1 AND T2.TRPR_INFO_NO = T.TRPR_INFO_NO AND T2.APLY_RCPT_SN = T.APLY_RCPT_SN LEFT JOIN (SELECT A.TRPR_INFO_NO, A.APLY_RCPT_SN, A.QUSTNB_TMPT_MNG_NO, A.QUSTNB_MNG_NO ,ROW_NUMBER() OVER (PARTITION BY A.QUSTNB_TMPT_MNG_NO, A.TRPR_INFO_NO, A.APLY_RCPT_SN ORDER BY A.REG_YMD DESC, A.MNG_SN DESC) AS RN FROM SBB600 A /* 설문지발송이력 - 보호자정성평가 */ INNER JOIN SAC100 B /* 공통코드값 */ ON B.ADDTNG_MNG_VALUE1 = A.QUSTNB_TMPT_MNG_NO AND B.CMMNS_CD_ID = 'QUSTNB_KND_SE_CD' AND B.CMMNS_CD_VALUE = '006' WHERE A.SRVY_ERA_SE_CD = '01') T3 ON T3.RN = 1 AND T3.TRPR_INFO_NO = T.TRPR_INFO_NO AND T3.APLY_RCPT_SN = T.APLY_RCPT_SN ) A LEFT JOIN SEA200 B ON B.TRPR_INFO_NO = A.TRPR_INFO_NO LEFT JOIN ( SELECT A.* , ROW_NUMBER() OVER(PARTITION BY A.TRPR_INFO_NO ORDER BY B.ADDTNG_MNG_VALUE1 DESC, A.MNG_SN DESC) AS RN , B.CMMNS_CD_VALUE_NM AS ACBG_SE_NM FROM SEA230 A /* 학력상태 */ LEFT JOIN SAC100 B ON B.CMMNS_CD_ID = 'ACBG_SE_CD' AND B.CMMNS_CD_VALUE = A.ACBG_SE_CD WHERE A.DEL_YN != 'Y' ) C ON C.TRPR_INFO_NO = B.TRPR_INFO_NO AND C.RN = 1 ) X )
WHERE 1=1 AND TRPR_INFO_NO = #{TRPR_INFO_NO} AND APLY_RCPT_SN = #{APLY_RCPT_SN}

