	/*SQL-ID : isry.csemd.mngrpage.aplcnttrprmng.mapper.AplcntTrprMngMapper updateCaseStts : 사례관리구분코드/사례대상자미신청사유구분코드 업데이트 - SEA200. LEE.SEOUNG.JAE */
    UPDATE SEA200 SET
        CASE_MNG_SE_CD = #{CASE_MNG_SE_CD}
        , CASE_TRPR_NOAP_CS_SE_CD = #{CASE_TRPR_NOAP_CS_SE_CD}
        , LAST_MDFR_ID = #{LAST_MDFR_ID}
    WHERE 1=1
        AND TRPR_INFO_NO = #{TRPR_INFO_NO}

